class MiniLangError(Exception):
    """Base exception for all minilang errors."""
    def __init__(self, message: str, position: int | None = None):
        super().__init__(message)
        self.position = position


class LexError(MiniLangError):
    """Raised when tokenization fails."""
    pass


class ParseError(MiniLangError):
    """Raised when parsing fails."""
    pass


class EvalError(MiniLangError):
    """Raised when evaluation fails."""
    pass

import re
from minilang.errors import LexError


class Token:
    __slots__ = ("kind", "value", "position")

    def __init__(self, kind: str, value: object, position: int):
        self.kind = kind
        self.value = value
        self.position = position

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r}, {self.position})"


# Token patterns, ordered by priority
TOKEN_PATTERNS: list[tuple[str, str]] = [
    ("COMMENT", r"#.*"),
    ("NUMBER", r"\d+\.\d*[eE][+-]?\d+|\d*\.\d+[eE][+-]?\d+|\.\d+|\d+\.(?=[^.\d]|\Z)|\d+\.\d*|\d+"),
    # The order above: we match complete numbers; but 1. (single dot at end) is caught separately as LexError
    ("STRING", r'"(?:[^"\\\n]|\\(?:n|t|r|"|\\))*"'),
    ("KEYWORD", r"true|false|and|or|not"),
    ("IDENT", r"[A-Za-z_][A-Za-z0-9_]*"),
    ("OP", r"==|!=|<=|>=|[+\-*/%^()<>=,.]"),
    ("WS", r"[ \t\n\r]+"),
]

# Compile combined regex
_parts = []
for kind, pat in TOKEN_PATTERNS:
    _parts.append(f"(?P<{kind}>{pat})")
_combined_re = re.compile("|".join(_parts))

# Numbers that end with a dot are illegal
_number_with_trailing_dot = re.compile(r"\d+\.$")


def tokenize(source: str) -> list:
    tokens: list[Token] = []
    pos = 0

    while pos < len(source):
        m = _combined_re.match(source, pos)
        if m is None:
            ch = source[pos]
            # Check for '=' not part of '=='
            if ch == "=" and (pos + 1 >= len(source) or source[pos + 1] != "="):
                raise LexError(f"invalid character: '=' (use '==' for equality)", pos)
            # Check for single '.' not part of a number
            if ch == ".":
                raise LexError(f"invalid number: trailing dot", pos)
            raise LexError(f"unexpected character: {ch!r}", pos)

        kind = m.lastgroup
        text = m.group()
        start = pos
        pos = m.end()

        if kind == "WS" or kind == "COMMENT":
            continue

        if kind == "NUMBER":
            # Check for trailing dot
            if text.endswith("."):
                raise LexError(f"invalid number: trailing dot", start)
            tokens.append(Token("NUMBER", text, start))
        elif kind == "STRING":
            # Process escapes
            s = text[1:-1]  # strip quotes
            value = _unescape_string(s, start)
            tokens.append(Token("STRING", value, start))
        elif kind == "KEYWORD":
            tokens.append(Token("KEYWORD", text, start))
        elif kind == "IDENT":
            tokens.append(Token("IDENT", text, start))
        elif kind == "OP":
            # Handle '.' appearing mid-number (not at end)
            if text == ".":
                raise LexError(f"invalid character: '.'", start)
            # Single '=' outside of '==' is caught above
            tokens.append(Token("OP", text, start))

    return tokens


def _unescape_string(s: str, pos: int) -> str:
    """Unescape a string literal, raising LexError on invalid escapes."""
    chars = []
    i = 0
    while i < len(s):
        if s[i] == "\\":
            if i + 1 >= len(s):
                raise LexError("unterminated string", pos)
            esc = s[i + 1]
            if esc == "n":
                chars.append("\n")
            elif esc == "t":
                chars.append("\t")
            elif esc == "r":
                chars.append("\r")
            elif esc == '"':
                chars.append('"')
            elif esc == "\\":
                chars.append("\\")
            else:
                raise LexError(f"invalid escape: \\{esc}", pos)
            i += 2
        else:
            chars.append(s[i])
            i += 1
    return "".join(chars)

from minilang.lexer import Token, tokenize
from minilang.errors import ParseError


# --- AST Node types ---

class NumberLiteral:
    __slots__ = ("value", "position")
    def __init__(self, value: float, position: int):
        self.value = value
        self.position = position

class StringLiteral:
    __slots__ = ("value", "position")
    def __init__(self, value: str, position: int):
        self.value = value
        self.position = position

class BooleanLiteral:
    __slots__ = ("value", "position")
    def __init__(self, value: bool, position: int):
        self.value = value
        self.position = position

class Identifier:
    __slots__ = ("name", "position")
    def __init__(self, name: str, position: int):
        self.name = name
        self.position = position

class UnaryOp:
    __slots__ = ("op", "operand", "position")
    def __init__(self, op: str, operand: object, position: int):
        self.op = op
        self.operand = operand
        self.position = position

class BinaryOp:
    __slots__ = ("op", "left", "right", "position")
    def __init__(self, op: str, left: object, right: object, position: int):
        self.op = op
        self.left = left
        self.right = right
        self.position = position

class FunctionCall:
    __slots__ = ("name", "args", "position")
    def __init__(self, name: str, args: list, position: int):
        self.name = name
        self.args = args
        self.position = position


class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Token:
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def expect(self, kind: str, value: str | None = None) -> Token:
        t = self.peek()
        if t is None:
            raise ParseError("unexpected end of input", -1)
        if t.kind != kind:
            raise ParseError(f"expected {kind}, got {t.kind}", t.position)
        if value is not None and t.value != value:
            raise ParseError(f"expected {value!r}, got {t.value!r}", t.position)
        return self.advance()

    def parse(self) -> object:
        if self.pos >= len(self.tokens):
            raise ParseError("empty expression", -1)
        node = self._expr()
        if self.pos < len(self.tokens):
            t = self.peek()
            raise ParseError(f"unexpected token: {t.value!r}", t.position)
        return node

    def _expr(self):
        return self._or_expr()

    def _or_expr(self):
        left = self._and_expr()
        while self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().value == "or":
            tok = self.advance()
            right = self._and_expr()
            left = BinaryOp("or", left, right, tok.position)
        return left

    def _and_expr(self):
        left = self._not_expr()
        while self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().value == "and":
            tok = self.advance()
            right = self._not_expr()
            left = BinaryOp("and", left, right, tok.position)
        return left

    def _not_expr(self):
        tok = self.peek()
        if tok is not None and tok.kind == "KEYWORD" and tok.value == "not":
            self.advance()
            operand = self._not_expr()
            return UnaryOp("not", operand, tok.position)
        return self._comparison()

    def _comparison(self):
        left = self._additive()
        tok = self.peek()
        if tok is not None and tok.kind == "OP" and tok.value in ("==", "!=", "<", "<=", ">", ">="):
            self.advance()
            right = self._additive()
            # Check that there isn't another comparison op (non-associative)
            next_tok = self.peek()
            if next_tok is not None and next_tok.kind == "OP" and next_tok.value in ("==", "!=", "<", "<=", ">", ">="):
                raise ParseError("chained comparison is not allowed", next_tok.position)
            return BinaryOp(tok.value, left, right, tok.position)
        return left

    def _additive(self):
        left = self._multiplicative()
        while self.peek() is not None and self.peek().kind == "OP" and self.peek().value in ("+", "-"):
            tok = self.advance()
            right = self._multiplicative()
            left = BinaryOp(tok.value, left, right, tok.position)
        return left

    def _multiplicative(self):
        left = self._unary()
        while self.peek() is not None and self.peek().kind == "OP" and self.peek().value in ("*", "/", "%"):
            tok = self.advance()
            right = self._unary()
            left = BinaryOp(tok.value, left, right, tok.position)
        return left

    def _unary(self):
        tok = self.peek()
        if tok is not None and tok.kind == "OP" and tok.value == "-":
            self.advance()
            operand = self._unary()
            return UnaryOp("-", operand, tok.position)
        return self._power()

    def _power(self):
        left = self._primary()
        tok = self.peek()
        if tok is not None and tok.kind == "OP" and tok.value == "^":
            self.advance()
            # Right-associative: right operand is unary
            right = self._unary()
            left = BinaryOp("^", left, right, tok.position)
        return left

    def _primary(self):
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", -1)

        if tok.kind == "NUMBER":
            self.advance()
            val = float(tok.value)
            return NumberLiteral(val, tok.position)
        elif tok.kind == "STRING":
            self.advance()
            return StringLiteral(tok.value, tok.position)
        elif tok.kind == "KEYWORD" and tok.value == "true":
            self.advance()
            return BooleanLiteral(True, tok.position)
        elif tok.kind == "KEYWORD" and tok.value == "false":
            self.advance()
            return BooleanLiteral(False, tok.position)
        elif tok.kind == "IDENT":
            self.advance()
            # Check if this is a function call
            if self.peek() is not None and self.peek().kind == "OP" and self.peek().value == "(":
                self.advance()  # consume (
                args = []
                if not (self.peek() is not None and self.peek().kind == "OP" and self.peek().value == ")"):
                    args.append(self._expr())
                    while self.peek() is not None and self.peek().kind == "OP" and self.peek().value == ",":
                        self.advance()  # consume ,
                        if self.peek() is None or (self.peek().kind == "OP" and self.peek().value == ")"):
                            raise ParseError("trailing comma not allowed", tok.position)
                        args.append(self._expr())
                self.expect("OP", ")")
                return FunctionCall(tok.value, args, tok.position)
            else:
                return Identifier(tok.name, tok.position)
        elif tok.kind == "OP" and tok.value == "(":
            self.advance()
            node = self._expr()
            self.expect("OP", ")")
            return node
        else:
            raise ParseError(f"unexpected token: {tok.value!r}", tok.position)


def parse(source: str) -> object:
    tokens = tokenize(source)
    # Filter out any tokens that are just standalone '.' (shouldn't happen after lexer fix, but safety)
    parser = Parser(tokens)
    return parser.parse()

import math
from minilang.errors import EvalError


def _check_arity(name: str, expected: int | tuple, actual: int):
    """Check arity and raise EvalError if wrong."""
    if isinstance(expected, int):
        if actual != expected:
            n_text = str(expected)
            raise EvalError(f"{name}() takes {n_text} argument(s), got {actual}")
    elif isinstance(expected, tuple):
        if actual not in expected:
            expected_list = sorted(expected)
            raise EvalError(
                f"{name}() takes {expected_list[0]} argument(s), got {actual}"
                if len(expected_list) == 1
                else f"{name}() takes {expected_list[0]} argument(s), got {actual}"
            )


def _to_formatted_number(x: float) -> str:
    """Format a number using the same rules as the REPL."""
    if x == float("inf") or x == float("-inf") or x != x:
        # Handle special cases
        r = repr(x)
        return r
    if x == int(x) and abs(x) < 2**53:
        return str(int(x))
    s = repr(x)
    # Remove trailing zeros and possible trailing dot
    if "." in s:
        s = s.rstrip("0")
        if s.endswith("."):
            s = s[:-1]
    return s


def builtin_abs(args: list) -> float:
    _check_arity("abs", 1, len(args))
    x = args[0]
    if not isinstance(x, (int, float)):
        raise EvalError(f"abs() requires a number, got {type(x).__name__}")
    return abs(x)


def builtin_min(args: list) -> float:
    if len(args) < 1:
        raise EvalError(f"min() takes 1 argument(s), got 0")
    for x in args:
        if not isinstance(x, (int, float)):
            raise EvalError(f"min() requires numbers")
    return min(args)


def builtin_max(args: list) -> float:
    if len(args) < 1:
        raise EvalError(f"max() takes 1 argument(s), got 0")
    for x in args:
        if not isinstance(x, (int, float)):
            raise EvalError(f"max() requires numbers")
    return max(args)


def builtin_round(args: list) -> float:
    x = args[0]
    if not isinstance(x, (int, float)):
        raise EvalError(f"round() requires a number")
    if len(args) == 1:
        return round(x)
    elif len(args) == 2:
        n = args[1]
        if not isinstance(n, (int, float)):
            raise EvalError(f"round() requires a number for n")
        if n != int(n):
            raise EvalError(f"round() requires an integer for n")
        return round(x, int(n))
    else:
        _check_arity("round", 1, len(args))


def builtin_len(args: list) -> float:
    _check_arity("len", 1, len(args))
    x = args[0]
    if not isinstance(x, str):
        raise EvalError(f"len() requires a string")
    return float(len(x))


def builtin_upper(args: list) -> str:
    _check_arity("upper", 1, len(args))
    x = args[0]
    if not isinstance(x, str):
        raise EvalError(f"upper() requires a string")
    return x.upper()


def builtin_lower(args: list) -> str:
    _check_arity("lower", 1, len(args))
    x = args[0]
    if not isinstance(x, str):
        raise EvalError(f"lower() requires a string")
    return x.lower()


def builtin_str_func(args: list) -> str:
    _check_arity("str", 1, len(args))
    x = args[0]
    if isinstance(x, bool):
        return "true" if x else "false"
    if isinstance(x, float):
        return _to_formatted_number(x)
    if isinstance(x, str):
        return x
    raise EvalError(f"str() received unsupported type")


def builtin_num(args: list) -> float:
    _check_arity("num", 1, len(args))
    x = args[0]
    if not isinstance(x, str):
        raise EvalError(f"num() requires a string")
    s = x.strip()
    try:
        return float(s)
    except ValueError:
        raise EvalError(f"cannot parse {s!r} as number")


def _if_thunk(args_evaluated: list, cond_idx: int, then_idx: int, else_idx: int, position: int | None):
    """Handle lazy evaluation for if()."""
    from minilang.evaluator import _eval_node
    cond = args_evaluated[0]
    if not isinstance(cond, bool):
        raise EvalError("if() condition must be a boolean", position)
    if cond:
        return True, then_idx
    else:
        return False, else_idx


# Registry of built-in functions
BUILTINS = {
    "abs": builtin_abs,
    "min": builtin_min,
    "max": builtin_max,
    "round": builtin_round,
    "len": builtin_len,
    "upper": builtin_upper,
    "lower": builtin_lower,
    "str": builtin_str_func,
    "num": builtin_num,
}

import math
from minilang.errors import EvalError
from minilang.parser import (
    NumberLiteral, StringLiteral, BooleanLiteral,
    Identifier, UnaryOp, BinaryOp, FunctionCall,
    parse as _parse,
)
from minilang.builtins import BUILTINS


def evaluate(source: str, env: dict | None = None) -> object:
    """Parse and evaluate a minilang expression."""
    if env is None:
        env = {}
    # Deep-copy the env so we don't mutate the caller's dict
    env_copy = dict(env)
    ast = _parse(source)
    return _eval_node(ast, env_copy)


def _eval_node(node: object, env: dict) -> object:
    """Evaluate an AST node in the given environment."""

    if isinstance(node, NumberLiteral):
        return node.value

    if isinstance(node, StringLiteral):
        return node.value

    if isinstance(node, BooleanLiteral):
        return node.value

    if isinstance(node, Identifier):
        return _resolve_name(node.name, node.position, env)

    if isinstance(node, UnaryOp):
        if node.op == "-":
            val = _eval_node(node.operand, env)
            if not isinstance(val, (int, float)):
                raise EvalError("unary minus requires a number", node.position)
            return -val
        elif node.op == "not":
            val = _eval_node(node.operand, env)
            if not isinstance(val, bool):
                raise EvalError("not requires a boolean", node.position)
            return not val
        else:
            raise EvalError(f"unknown unary operator: {node.op}", node.position)

    if isinstance(node, BinaryOp):
        return _eval_binary(node, env)

    if isinstance(node, FunctionCall):
        return _eval_call(node, env)

    raise EvalError(f"unknown AST node: {type(node)}")


def _resolve_name(name: str, position: int, env: dict) -> object:
    """Look up a name in the environment."""
    if name in env:
        val = env[name]
        if isinstance(val, bool):
            return val
        if isinstance(val, float):
            return val
        if isinstance(val, str):
            return val
        if isinstance(val, int):
            raise EvalError(f"unsupported value for {name}: {val!r}", position)
        raise EvalError(f"unsupported value for {name}: {val!r}", position)
    # Check built-ins (as variable access, not function call - this should raise)
    if name in BUILTINS:
        raise EvalError(f"undefined variable: {name}", position)
    raise EvalError(f"undefined variable: {name}", position)


def _eval_binary(node: BinaryOp, env: dict) -> object:
    op = node.op

    # Short-circuit logical operators
    if op == "or":
        left = _eval_node(node.left, env)
        if not isinstance(left, bool):
            raise EvalError("or requires boolean operands", node.position)
        if left:
            return True
        right = _eval_node(node.right, env)
        if not isinstance(right, bool):
            raise EvalError("or requires boolean operands", node.position)
        return right

    if op == "and":
        left = _eval_node(node.left, env)
        if not isinstance(left, bool):
            raise EvalError("and requires boolean operands", node.position)
        if not left:
            return False
        right = _eval_node(node.right, env)
        if not isinstance(right, bool):
            raise EvalError("and requires boolean operands", node.position)
        return right

    left = _eval_node(node.left, env)
    right = _eval_node(node.right, env)

    if op == "+":
        if isinstance(left, float) and isinstance(right, float):
            return left + right
        if isinstance(left, str) and isinstance(right, str):
            return left + right
        raise EvalError(
            f"cannot add {type(left).__name__} and {type(right).__name__}",
            node.position,
        )

    if op == "-":
        _check_numeric_binary(op, left, right, node.position)
        return left - right

    if op == "*":
        _check_numeric_binary(op, left, right, node.position)
        return left * right

    if op == "/":
        _check_numeric_binary(op, left, right, node.position)
        if right == 0.0:
            raise EvalError("division by zero", node.position)
        return left / right

    if op == "%":
        _check_numeric_binary(op, left, right, node.position)
        if right == 0.0:
            raise EvalError("modulo by zero", node.position)
        return left % right

    if op == "^":
        _check_numeric_binary(op, left, right, node.position)
        result = left ** right
        if isinstance(result, complex) or result != result:
            raise EvalError("result is not a real number", node.position)
        return result

    if op in ("==", "!="):
        if type(left) != type(right):
            eq = False
        else:
            eq = left == right
        if op == "==":
            return eq
        else:
            return not eq

    if op in ("<", "<=", ">", ">="):
        if isinstance(left, float) and isinstance(right, float):
            pass  # OK
        elif isinstance(left, str) and isinstance(right, str):
            pass  # OK
        else:
            raise EvalError(
                f"cannot compare {type(left).__name__} and {type(right).__name__}",
                node.position,
            )
        if op == "<":
            return left < right
        elif op == "<=":
            return left <= right
        elif op == ">":
            return left > right
        else:  # >=
            return left >= right

    raise EvalError(f"unknown operator: {op}", node.position)


def _check_numeric_binary(op: str, left: object, right: object, position: int):
    if not (isinstance(left, float) and isinstance(right, float)):
        raise EvalError(
            f"{op} requires numbers, got {type(left).__name__} and {type(right).__name__}",
            position,
        )


def _eval_call(node: FunctionCall, env: dict) -> object:
    name = node.name

    # Check if it's a built-in
    if name in BUILTINS:
        args = []
        # Evaluate all args first (except for if which is special)
        if name == "if":
            if len(node.args) != 3:
                raise EvalError(
                    f"if() takes 3 argument(s), got {len(node.args)}", node.position
                )
            # Evaluate condition
            cond = _eval_node(node.args[0], env)
            if not isinstance(cond, bool):
                raise EvalError("if() condition must be a boolean", node.position)
            if cond:
                return _eval_node(node.args[1], env)
            else:
                return _eval_node(node.args[2], env)
        else:
            for arg_node in node.args:
                args.append(_eval_node(arg_node, env))
            return BUILTINS[name](args)

    # Unknown function
    raise EvalError(f"undefined function: {name}", node.position)

import sys
from minilang import evaluate, parse, tokenize
from minilang.errors import MiniLangError, LexError, ParseError, EvalError


def _format_value(val: object) -> str:
    """Format a value for REPL output following rule 33."""
    if isinstance(val, bool):
        return "true" if val else "false"
    if isinstance(val, float):
        if val == float("inf") or val == float("-inf") or val != val:
            return repr(val)
        if val == int(val) and abs(val) < 2 ** 53:
            # Integral number, no decimal part
            return str(int(val))
        s = repr(val)
        # Remove trailing zeros and possible trailing dot
        if "." in s:
            s = s.rstrip("0")
            if s.endswith("."):
                s = s[:-1]
        return s
    if isinstance(val, str):
        # Re-escape: wrap in double quotes, escape special chars
        escaped = (
            val.replace("\\", "\\\\")
            .replace("\n", "\\n")
            .replace("\t", "\\t")
            .replace("\r", "\\r")
            .replace('"', '\\"')
        )
        return f'"{escaped}"'
    return repr(val)


def _repl():
    env: dict = {}
    for line_raw in sys.stdin:
        line = line_raw.rstrip("\n\r")

        # Blank or whitespace-only
        if not line.strip():
            continue

        # :quit
        if line.strip() == ":quit":
            sys.exit(0)

        # :vars
        if line.strip() == ":vars":
            if env:
                for name in sorted(env):
                    print(f"{name} = {_format_value(env[name])}")
            continue

        # <ident> = <expr> (a single '=' not followed by '=')
        stripped = line.strip()
        eq_pos = _find_assignment_eq(stripped)
        if eq_pos is not None:
            ident = stripped[:eq_pos].strip()
            expr_src = stripped[eq_pos + 1:].strip()
            if not ident:
                # Try to evaluate the whole line
                try:
                    result = evaluate(line, env)
                    print(_format_value(result))
                except MiniLangError as e:
                    print(f"error: {e}")
                continue
            # Validate identifier
            if not ident.isidentifier():
                print(f"error: invalid identifier: {ident!r}")
                continue
            try:
                result = evaluate(expr_src, env)
                env[ident] = result
            except MiniLangError as e:
                print(f"error: {e}")
            continue

        # Evaluate as expression
        try:
            result = evaluate(line, env)
            print(_format_value(result))
        except MiniLangError as e:
