    depth = 0
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        elif ch == '=' and depth == 0:
            # Check if this is '==' 
            if i + 1 < len(s) and s[i + 1] == '=':
